["वैनगंगा नदीचा उगम कोठे होतो?",["महाराष्ट्र (गोंदिया जिल्हा)","मध्य प्रदेश (शिवनी जिल्हा)","छत्तीसगड","तेलंगणा"],1,"वैनगंगा मध्य प्रदेशातील शिवनी जिल्ह्यात मुंडारा (मुंडारा टेकड्या) जवळ उगम पावते आणि विदर्भातून वाहत वर्धेला मिळून प्राणहिता बनते.",{"i":"ge5-017"}],
["प्रवरा नदी कोणत्या नदीची उपनदी आहे?",["गोदावरी","भीमा","कृष्णा","तापी"],0,"प्रवरा (भंडारदरा धरण) नेवासेजवळ गोदावरीला मिळते. गोदावरीच्या इतर उपनद्या: दारणा, कादवा, शिवना, पूर्णा, मांजरा, प्राणहिता, इंद्रावती.",{"i":"ge5-018"}],
["मांजरा नदी कोणत्या नदीची उपनदी आहे?",["वैनगंगा","कृष्णा","भीमा","गोदावरी"],3,"मांजरा बालाघाट डोंगरात (बीड) उगम पावून लातूर, नांदेडमधून वाहत तेलंगणात गोदावरीला मिळते. लातूरच्या पाणीपुरवठ्याचा मुख्य स्रोत मांजरा धरण.",{"i":"ge5-019"}],
["पूर्णा नदी (विदर्भ) कोणत्या नदीची उपनदी आहे?",["पैनगंगा","गोदावरी","वर्धा","तापी"],3,"विदर्भातील पूर्णा (उगम गाविलगड डोंगर, मध्य प्रदेश) तापीला मिळते. मराठवाड्यातील दुसरी पूर्णा नदी गोदावरीला मिळते, त्यामुळे संदर्भ पाहणे आवश्यक.",{"i":"ge5-020"}],
["इंद्रायणी नदीकाठी कोणती तीर्थक्षेत्रे आहेत?",["आळंदी व देहू","पंढरपूर व तुळजापूर","नाशिक व त्र्यंबकेश्वर","जेजुरी व मोरगाव"],0,"आळंदी (संत ज्ञानेश्वर समाधी) व देहू (संत तुकाराम) इंद्रायणीकाठी आहेत; इंद्रायणी भीमेची उपनदी. पंढरपूर भीमा (चंद्रभागा) काठी, नाशिक गोदावरीकाठी.",{"i":"ge5-021"}]
