re3:[
["CAT = DBU, तर DOG = ?",["FQI","EPG","DPH","EPH"],3,"प्रत्येक अक्षर एकाने पुढे: C→D, A→B, T→U. तसेच D→E, O→P, G→H → EPH.",{"i":"re3-001"}],
["CAT = 24, तर BAT = ?",["24","22","23","21"],2,"अक्षरांच्या क्रमांकांची बेरीज: CAT = 3 + 1 + 20 = 24. BAT = 2 + 1 + 20 = 23.",{"i":"re3-002"}],
["GOD हा शब्द उलट वर्णमालेत कसा लिहिला जाईल?",["TMW","TLW","SLW","TLV"],1,"उलट वर्णमालेत अक्षर = 27 − क्रमांक. G(7) → 20 = T, O(15) → 12 = L, D(4) → 23 = W → TLW.",{"i":"re3-003"}],
["'sa na pa' = 'तो चांगला आहे', 'pa ta' = 'आहे का'. तर 'आहे' = ?",["pa","na","sa","ta"],0,"दोन्ही वाक्यांत 'आहे' सामाईक आहे आणि संकेतांत 'pa' सामाईक आहे. म्हणून 'आहे' = pa.",{"i":"re3-004"}],
["जर CAT = 3120, तर DOG = ?",["4157","4158","4147","3157"],0,"प्रत्येक अक्षराच्या जागी त्याचा क्रमांक लिहिला आहे: C3 A1 T20 → 3120. D4 O15 G7 → 4157.",{"i":"re3-005","y":"pyq"}],
["जर FRIEND = HUMJTK, तर CANDLE = ?",["EDRIRL","DCQHQK","ESJFME","EDRJRL"],0,"FRIEND → HUMJTK मध्ये अक्षरे +2, +3, +4, +5, +6, +7 ने पुढे गेली (F→H, R→U, I→M, E→J, N→T, D→K). CANDLE: C+2 = E, A+3 = D, N+4 = R, D+5 = I, L+6 = R, E+7 = L → EDRIRL.",{"i":"re3-006","y":"pyq"}],
["एका सांकेतिक भाषेत 'आंबा' म्हणजे 'केळ', 'केळ' म्हणजे 'पेरू', 'पेरू' म्हणजे 'सफरचंद'. तर पिवळे फळ कोणते?",["आंबा","केळ","पेरू","सफरचंद"],2,"खऱ्या भाषेत पिवळे फळ केळे आहे. या सांकेतिक भाषेत 'केळ' ला 'पेरू' म्हणतात. म्हणून उत्तर 'पेरू'. असे प्रश्न नेहमी: खरे उत्तर शोधा आणि मग त्याचे सांकेतिक नाव द्या.",{"i":"re3-007","y":"pyq"}],
["एका सांकेतिक भाषेत LANGUAGE हा शब्द NDPJWDIH असा लिहितात. तर OFFICIAL कसा लिहाल?",["QIILELCM","QIHLELCO","QIILEJCM","QIHLEKCO"],1,"LANGUAGE → NDPJWDIH: अक्षरे आलटून पालटून +2 व +3 ने पुढे (L+2 = N, A+3 = D, N+2 = P, G+3 = J …). OFFICIAL: O+2 = Q, F+3 = I, F+2 = H, I+3 = L, C+2 = E, I+3 = L, A+2 = C, L+3 = O → QIHLELCO.",{"i":"re3-008","y":"2018","n":62,"v":"k"}],
["एका सांकेतिक भाषेत THANKS हे SKNTHA असे लिहितात. तर STUPID कसे लिहाल?",["DIPUTS","DIPSTU","DISPUT","DIPUST"],1,"THANKS (T1 H2 A3 N4 K5 S6) → SKNTHA म्हणजे क्रम 6, 5, 4, 1, 2, 3 (शेवटची तीन उलटी, मग पहिली तीन). STUPID: D, I, P, S, T, U → DIPSTU.",{"i":"re3-009","y":"2026"}],
["एका सांकेतिक भाषेत '1 2 4' म्हणजे 'fresh and juicy', '5 4 6' म्हणजे 'eat juicy fruits' आणि '6 7 8' म्हणजे 'fruit is ripe'. तर 'eat' साठी कोणता अंक आहे?",["4","6","5","7"],2,"पहिल्या दोन ओळींत 'juicy' व 4 समान → juicy = 4. दुसऱ्या व तिसऱ्या ओळींत 'fruits/fruit' व 6 समान → fruit = 6. म्हणून '5 4 6' मध्ये उरलेला 5 = eat.",{"i":"re3-010","y":"2023","n":36,"src":"गट-क मुख्य परीक्षा 2022, कर सहायक पेपर-II (4 मार्च 2023)","p":"ta"}],
["एका सांकेतिक भाषेत APTITUDE हा शब्द ELXEXQHA असा लिहितात. तर ELEPHANT हा शब्द कसा लिहिला जाईल?",["IHILLWRP","IHINNWRP","IOILLWRP","IHITLWRP"],0,"A→E (+4), P→L (−4), T→X (+4), I→E (−4)… असे एकाआड +4 व −4. ELEPHANT: E+4=I, L−4=H, E+4=I, P−4=L, H+4=L, A−4=W, N+4=R, T−4=P → IHILLWRP.",{"i":"re3-011","y":"2023","n":37,"src":"गट-क मुख्य परीक्षा 2022, कर सहायक पेपर-II (4 मार्च 2023)","p":"ta"}],
["एका सांकेतिक भाषेत MANGO = NBOHP. तर APPLE = ?",["BPQMF","BQQME","ZOOKD","BQQMF"],3,"प्रत्येक अक्षर +1: A→B, P→Q, P→Q, L→M, E→F = BQQMF.",{"i":"re3-012"}],
["एका सांकेतिक भाषेत ROSE = 6821, CHAIR = 73456 आणि PREACH = 961473. तर SEARCH = ?",["214673","214763","241673","216473"],0,"ROSE वरून R=6, O=8, S=2, E=1. CHAIR वरून C=7, H=3, A=4, I=5. म्हणून S E A R C H = 2 1 4 6 7 3 = 214673.",{"i":"re3-013"}],
["COMPUTER हा शब्द एका सांकेतिक भाषेत RETUPMOC असा लिहितात. तर PRINTER कसा लिहितील?",["RETNRIP","RETNIRP","RTENIRP","PRETNIR"],1,"शब्द उलट्या क्रमाने लिहिला आहे. PRINTER उलटा = RETNIRP.",{"i":"re3-014"}],
["जर 'आकाश'ला 'समुद्र', 'समुद्र'ला 'पाणी', 'पाणी'ला 'हवा' आणि 'हवा'ला 'ढग' म्हटले, तर मासे कशात राहतात?",["समुद्र","पाणी","हवा","ढग"],2,"मासे पाण्यात राहतात आणि या भाषेत 'पाणी'ला 'हवा' म्हणतात. म्हणून उत्तर 'हवा'.",{"i":"re3-015"}],
["एका सांकेतिक भाषेत 'pit na sa' म्हणजे 'you are good', 'na ka da' म्हणजे 'they are bad' आणि 'sa ka la' म्हणजे 'good and bad'. तर 'are' साठी कोणता शब्द आहे?",["pit","ka","sa","na"],3,"पहिल्या व दुसऱ्या वाक्यात 'are' समान आहे आणि दोन्ही संकेतांत 'na' समान आहे. (good = sa, bad = ka.)",{"i":"re3-016"}],
["एका सांकेतिक भाषेत 'TEACHER' = 'VGCEJGT'. तर 'STUDENT' = ?",["UVWFGPV","UVWFGOV","TUVEFOU","UVWGFPV"],0,"प्रत्येक अक्षर +2: T→V, E→G, A→C … म्हणून S→U, T→V, U→W, D→F, E→G, N→P, T→V = UVWFGPV.",{"i":"re3-017"}],
["जर A = 1, B = 2, … Z = 26 असेल, तर 'BAD' या शब्दाच्या अक्षरांच्या किमतींची बेरीज किती?",["6","7","8","9"],1,"B = 2, A = 1, D = 4. बेरीज 2 + 1 + 4 = 7.",{"i":"re3-018"}],
["एका सांकेतिक भाषेत 'CAT' = 24 (3 + 1 + 20). त्याच नियमाने 'DOG' = ?",["25","24","26","27"],2,"D = 4, O = 15, G = 7. बेरीज 4 + 15 + 7 = 26.",{"i":"re3-019"}]
],
