["मुरुड-जंजिरा हा जलदुर्ग कोणाच्या ताब्यात होता?",["आंग्रे","सिद्दी","पोर्तुगीज","इंग्रज"],1,"रायगड जिल्ह्यातील मुरुडजवळचा जंजिरा किल्ला सिद्दींच्या ताब्यात होता. मराठ्यांनी अनेक प्रयत्न करूनही तो जिंकता आला नाही.",{"i":"gk1-103"}],
["देवगिरी (दौलताबाद) ही कोणत्या राजवंशाची राजधानी होती?",["यादव","राष्ट्रकूट","सातवाहन","चालुक्य"],0,"देवगिरी ही यादवांची राजधानी होती. 1327 मध्ये मुहम्मद बिन तुघलकाने राजधानी दिल्लीहून येथे हलवून तिचे नाव दौलताबाद केले.",{"i":"gk1-104"}],
["'बीबी का मकबरा' कोठे आहे?",["नागपूर","दौलताबाद","बुऱ्हाणपूर","छत्रपती संभाजीनगर"],3,"छत्रपती संभाजीनगर येथील बीबी का मकबरा औरंगजेबाचा मुलगा आझमशाह याने आई दिलरस बानो बेगम हिच्या स्मरणार्थ बांधला. ताजमहालासारखा दिसल्याने त्याला 'दख्खनचा ताज' म्हणतात.",{"i":"gk1-105"}],
["वेरूळ लेण्यांचे वैशिष्ट्य कोणते?",["फक्त जैन लेणी","फक्त बौद्ध लेणी","बौद्ध, हिंदू व जैन लेणी एकाच ठिकाणी","फक्त हिंदू लेणी"],2,"वेरूळ येथे बौद्ध, हिंदू व जैन अशा तिन्ही धर्मांची लेणी आहेत; त्यामुळे ते धार्मिक सहिष्णुतेचे प्रतीक मानले जाते. अजिंठा लेणी मुख्यतः बौद्ध असून भित्तिचित्रांसाठी प्रसिद्ध.",{"i":"gk1-106"}],
["कार्ले (कार्ला) येथील प्रसिद्ध लेणी कोणत्या धर्माशी संबंधित आहेत?",["जैन","बौद्ध","हिंदू","शीख"],1,"पुणे जिल्ह्यात लोणावळ्याजवळील कार्ले लेण्यांतील चैत्यगृह भारतातील सर्वात मोठ्या बौद्ध चैत्यगृहांपैकी एक आहे.",{"i":"gk1-107"}],
["संत ज्ञानेश्वरांची समाधी कोठे आहे?",["आळंदी","देहू","पैठण","नेवासे"],0,"संत ज्ञानेश्वरांनी 1296 मध्ये पुणे जिल्ह्यातील आळंदी येथे इंद्रायणीकाठी संजीवन समाधी घेतली.",{"i":"gk1-108"}],
["महाराष्ट्रातील साडेतीन शक्तिपीठांपैकी 'अर्धे पीठ' कोणते मानले जाते?",["कोल्हापूर","तुळजापूर","माहूर","सप्तशृंगी (वणी)"],3,"कोल्हापूरची महालक्ष्मी, तुळजापूरची तुळजाभवानी व माहूरची रेणुका ही पूर्ण पीठे; नाशिक जिल्ह्यातील वणीची सप्तशृंगी हे अर्धे पीठ.",{"i":"gk1-109"}],
["तुळजाभवानीचे मंदिर कोणत्या जिल्ह्यात आहे?",["सोलापूर","धाराशिव","लातूर","बीड"],1,"तुळजापूर हे धाराशिव (पूर्वीचे उस्मानाबाद) जिल्ह्यात आहे. तुळजाभवानी ही छत्रपती शिवाजी महाराजांची कुलदेवता.",{"i":"gk1-110"}],
["अष्टविनायकांपैकी मोरगावचा गणपती कोणत्या नावाने ओळखला जातो?",["सिद्धिविनायक","चिंतामणी","मयूरेश्वर","वरदविनायक"],2,"पुणे जिल्ह्यातील मोरगावचा मयूरेश्वर हा अष्टविनायक यात्रेतील पहिला गणपती मानला जातो. थेऊरचा चिंतामणी, सिद्धटेकचा सिद्धिविनायक, महडचा वरदविनायक.",{"i":"gk1-111"}],
["शनि शिंगणापूर कोणत्या जिल्ह्यात आहे?",["बीड","नाशिक","पुणे","अहिल्यानगर"],3,"शनि शिंगणापूर अहिल्यानगर जिल्ह्यात नेवासा तालुक्यात आहे. येथील घरांना दरवाजे नसतात अशी प्रसिद्धी आहे.",{"i":"gk1-112"}],
["वारली चित्रकला प्रामुख्याने कोणत्या जिल्ह्यातील आदिवासींची आहे?",["पालघर","गडचिरोली","नंदुरबार","अमरावती"],0,"वारली ही पालघर (पूर्वीचा ठाणे) जिल्ह्यातील डहाणू-तलासरी भागातील वारली आदिवासींची पारंपरिक चित्रकला आहे. तांदळाच्या पिठाच्या पांढऱ्या रंगाने वर्तुळ, त्रिकोण व रेषांनी चित्रे काढली जातात.",{"i":"gk1-113"}],
["वीरांच्या पराक्रमाचे वर्णन करणाऱ्या मराठी लोककाव्य प्रकाराला काय म्हणतात?",["लावणी","पोवाडा","भारूड","ओवी"],1,"पोवाडा हा शाहिरांनी गायलेला वीररसप्रधान प्रकार आहे; उदा. अफझलखान वधाचा पोवाडा. लावणी शृंगारप्रधान, भारूड हा संतांचा रूपकात्मक उपदेशपर प्रकार.",{"i":"gk1-114"}],
["GI मानांकन मिळालेली 'कोल्हापुरी' ही कोणती वस्तू आहे?",["गूळ","साडी","चप्पल","हळद"],2,"कोल्हापुरी चप्पल हाताने बनवलेली चामड्याची पादत्राणे असून तिला महाराष्ट्र व कर्नाटकातील काही जिल्ह्यांसाठी GI मानांकन मिळाले आहे.",{"i":"gk1-115"}],
["कोणत्या शहराला 'संत्रानगरी' (Orange City) म्हणतात?",["वर्धा","अमरावती","अकोला","नागपूर"],3,"नागपूर संत्र्यांसाठी प्रसिद्ध असून नागपुरी संत्र्याला GI मानांकन आहे. नागपूर ही राज्याची उपराजधानी आहे.",{"i":"gk1-116"}],
["GI मानांकन मिळालेली 'सोलापुरी' ही प्रसिद्ध वस्तू कोणती?",["चादर","चप्पल","साडी","पापड"],0,"सोलापूर हे हातमाग व यंत्रमागावरील चादरी व टॉवेलसाठी प्रसिद्ध असून सोलापुरी चादरीला GI मानांकन आहे.",{"i":"gk1-117"}],
["राष्ट्रीय संरक्षण प्रबोधिनी (NDA) कोठे आहे?",["देवळाली (नाशिक)","खडकवासला (पुणे)","कामठी (नागपूर)","अहिल्यानगर"],1,"NDA ही तिन्ही सेनादलांची संयुक्त प्रशिक्षण संस्था पुण्याजवळ खडकवासला येथे आहे.",{"i":"gk1-118"}],
["भाभा अणुसंशोधन केंद्र (BARC) कोठे आहे?",["पुणे","तारापूर","ट्रॉम्बे (मुंबई)","कल्पक्कम"],2,"BARC मुंबईतील ट्रॉम्बे येथे आहे. भारताच्या अणुकार्यक्रमाचे जनक डॉ. होमी भाभा यांच्या नावाने ते ओळखले जाते.",{"i":"gk1-119"}],
["फिल्म अँड टेलिव्हिजन इन्स्टिट्यूट ऑफ इंडिया (FTII) कोठे आहे?",["नागपूर","मुंबई","पुणे","कोल्हापूर"],2,"FTII पुण्यातील प्रभात फिल्म कंपनीच्या जुन्या स्टुडिओच्या जागेवर आहे.",{"i":"gk1-120"}],
["राष्ट्रीय रासायनिक प्रयोगशाळा (NCL) कोठे आहे?",["मुंबई","पुणे","नागपूर","नाशिक"],1,"CSIR ची राष्ट्रीय रासायनिक प्रयोगशाळा पुण्यात पाषाण येथे आहे. नागपूरला CSIR ची NEERI (राष्ट्रीय पर्यावरण अभियांत्रिकी संशोधन संस्था) आहे.",{"i":"gk1-121"}]
